-- Fluent Event — Database Schema (MySQL). GENERATED by gen_schema.py — do not hand-edit.
-- Only our wp_fe_* tables are defined here. WP core tables (wp_posts,
-- wp_postmeta, wp_users) and the taxonomy tables are NOT created by us — we
-- REFERENCE them (see footer + db/implementation.md for how). FK columns that
-- point at WP core (post_id, created_by, user_id) carry no DB FK —
-- enforced in app (dbDelta strips core FKs; engine/collation portability).
-- Event = CPT hybrid (wp_posts + wp_postmeta + wp_fe_event_details post_id 1:1).
-- Ticketing: event -> ticket_types -> guests (1 row per ticket; the is_buyer=1 row
-- of an order carries order/payment fields, NULL on companion rows).

SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE `wp_fe_calendars` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `title` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `description` TEXT NULL,
  `visibility` VARCHAR(64) NOT NULL DEFAULT 'public' COMMENT 'public | private | unlisted',
  `status` VARCHAR(64) NOT NULL DEFAULT 'active' COMMENT 'active | archived | draft',
  `settings` JSON NULL COMMENT 'Everything settings like logo url, cover url, roles, preferences etc.',
  `created_by` BIGINT UNSIGNED NOT NULL COMMENT 'User id connected to wp_users table',
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_calendars_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `wp_fe_meta` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `object_type` VARCHAR(64) NOT NULL,
  `object_id` BIGINT UNSIGNED NULL,
  `meta_key` VARCHAR(255) NOT NULL,
  `value` LONGTEXT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_meta_lookup` (`object_type`, `object_id`, `meta_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `wp_fe_notifications` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT UNSIGNED NULL,
  `action` VARCHAR(128) NOT NULL,
  `object_type` VARCHAR(64) NULL,
  `object_id` BIGINT UNSIGNED NULL,
  `title` VARCHAR(255) NULL,
  `content` TEXT NULL,
  `route` TEXT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `wp_fe_notification_users` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `object_type` VARCHAR(64) NOT NULL,
  `notification_type` VARCHAR(128) NOT NULL,
  `object_id` BIGINT UNSIGNED NOT NULL,
  `user_id` BIGINT UNSIGNED NOT NULL,
  `is_read` TINYINT(1) NOT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_notif_user` (`user_id`, `object_type`, `object_id`, `notification_type`),
  KEY `idx_notif_user_inbox` (`user_id`, `is_read`, `object_type`),
  KEY `idx_notif_user_object` (`object_id`, `is_read`, `object_type`, `notification_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `wp_fe_event_details` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `post_id` BIGINT UNSIGNED NOT NULL,
  `calendar_id` BIGINT UNSIGNED NOT NULL,
  `parent_event_id` BIGINT UNSIGNED NULL,
  `status` VARCHAR(64) NOT NULL DEFAULT 'public' COMMENT 'public | private | draft | archived',
  `start_at` DATETIME NOT NULL,
  `end_at` DATETIME NOT NULL,
  `timezone` VARCHAR(64) NULL COMMENT 'To display the organizer local time',
  `venue_type` VARCHAR(64) NULL DEFAULT 'offline' COMMENT 'offline | online | hybrid',
  `form_fields` JSON NULL COMMENT 'For custom form field per guests',
  `settings` JSON NULL COMMENT 'Event settings: logo, cover url, roles, customization, join policy, waitlist enabled etc.',
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_events_post` (`post_id`),
  KEY `idx_event_window` (`start_at`, `end_at`),
  KEY `idx_event_parent` (`parent_event_id`, `start_at`),
  KEY `fk_events_calendar_startat` (`calendar_id`, `start_at`),
  CONSTRAINT `fk_event_details_calendar_id` FOREIGN KEY (`calendar_id`) REFERENCES `wp_fe_calendars` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_event_details_parent_event_id` FOREIGN KEY (`parent_event_id`) REFERENCES `wp_fe_event_details` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `wp_fe_ticket_types` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `event_id` BIGINT UNSIGNED NOT NULL,
  `tier` VARCHAR(128) NOT NULL,
  `description` VARCHAR(255) NULL,
  `price` DECIMAL(10,2) NOT NULL,
  `slot` INT NULL COMMENT 'NULL = unlimited',
  `sold` INT NOT NULL,
  `min_per_reg` INT NOT NULL DEFAULT 1,
  `max_per_reg` INT NULL COMMENT 'NULL = unlimited',
  `sale_start_at` DATETIME NULL,
  `sale_end_at` DATETIME NULL,
  `status` VARCHAR(64) NOT NULL DEFAULT 'active' COMMENT 'active | inactive',
  `sort_order` INT NOT NULL,
  `settings` JSON NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_ticket_types_event_id_idx` (`event_id`),
  CONSTRAINT `fk_ticket_types_event_id` FOREIGN KEY (`event_id`) REFERENCES `wp_fe_event_details` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `wp_fe_guests` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `event_id` BIGINT UNSIGNED NOT NULL,
  `calendar_id` BIGINT UNSIGNED NOT NULL,
  `ticket_type_id` BIGINT UNSIGNED NULL,
  `group_id` VARCHAR(64) NOT NULL,
  `is_buyer` TINYINT(1) NOT NULL DEFAULT 0 COMMENT 'If he is the buyer of the registration',
  `name` VARCHAR(255) NULL,
  `email` VARCHAR(192) NULL,
  `user_id` BIGINT UNSIGNED NULL,
  `status` VARCHAR(64) NOT NULL COMMENT 'approved | checked_in | cancelled',
  `form_response` JSON NULL COMMENT 'Custom form field response',
  `hash` VARCHAR(64) NULL COMMENT 'Unique hash for each ticket',
  `checked_in_at` DATETIME NULL,
  `payment_status` VARCHAR(64) NULL COMMENT 'paid | unpaid | refunded etc.',
  `payment_ref` VARCHAR(255) NULL,
  `price` DECIMAL(10,2) NULL,
  `paid_at` DATETIME NULL,
  `source` VARCHAR(64) NULL COMMENT 'invite | community | requested etc.',
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_guests_hash` (`hash`),
  KEY `idx_guest_event_status` (`event_id`, `status`),
  KEY `idx_guest_calendar` (`calendar_id`, `status`),
  KEY `idx_guest_order` (`group_id`),
  KEY `idx_guest_email` (`email`),
  KEY `fk_guests_ticket_type_id` (`ticket_type_id`),
  CONSTRAINT `fk_guests_event_id` FOREIGN KEY (`event_id`) REFERENCES `wp_fe_event_details` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_guests_calendar_id` FOREIGN KEY (`calendar_id`) REFERENCES `wp_fe_calendars` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_guests_ticket_type_id` FOREIGN KEY (`ticket_type_id`) REFERENCES `wp_fe_ticket_types` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET FOREIGN_KEY_CHECKS = 1;

